void hide(){getWindow().getDecorView().setSystemUiVisibility(5894|1024|512|4096);}int dp(float n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}GradientDrawable shape(int c,int s){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(12));if(s!=0)d.setStroke(dp(1),s);return d;}TextView label(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;}LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);return l;}Button btn(String s,int c){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setTextColor(c==GR?BG:TX);b.setAllCaps(false);b.setTypeface(null,Typeface.BOLD);b.setBackground(shape(c,0));return b;}void reset(){root=col();root.setBackgroundColor(BG);setContentView(root);hide();}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}void err(String t,String s){new AlertDialog.Builder(this).setTitle(t).setMessage(s==null?"Unknown error":s).setPositiveButton("OK",null).show();}boolean connected(){if(sec.getString("github_token","").isEmpty()){setup();return false;}return true;}
