void setup(){LinearLayout box=col();box.setPadding(dp(8),0,dp(8),0);box.addView(label("GitHub token is encrypted on this device. For repository creation and workflow files, token needs repository and workflow permissions. OpenAI key is optional for AI chat.",12,MU));EditText gh=new EditText(this);gh.setSingleLine(true);gh.setHint("GitHub Personal Access Token");gh.setInputType(129);gh.setText(sec.getString("github_token",""));box.addView(gh);EditText ai=new EditText(this);ai.setSingleLine(true);ai.setHint("OpenAI API key (optional)");ai.setInputType(129);ai.setText(sec.getString("openai_key",""));box.addView(ai);new AlertDialog.Builder(this).setTitle("Connect DevStudio").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Verify & save",(d,w)->{String token=gh.getText().toString().trim(),key=ai.getText().toString().trim();if(token.isEmpty()){toast("GitHub token required");return;}ex.execute(()->{try{String login=api(token,"GET","/user",null).optString("login","");if(login.isEmpty())throw new Exception("Invalid GitHub token");sec.edit().putString("github_token",token).putString("github_login",login).putString("openai_key",key).apply();runOnUiThread(()->{home();toast("Connected as "+login);});}catch(Exception e){runOnUiThread(()->err("GitHub connection failed",e.getMessage()));}});}).show();}
LinkedHashMap<String,String> starter(String pkg){LinkedHashMap<String,String> f=new LinkedHashMap<>();f.put("settings.gradle","pluginManagement { repositories { google(); mavenCentral(); gradlePluginPortal() } }\ndependencyResolutionManagement { repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS); repositories { google(); mavenCentral() } }\nrootProject.name = 'AndroidProject'\ninclude ':app'\n");f.put("build.gradle","plugins { id 'com.android.application' version '8.7.3' apply false }\n");f.put("gradle.properties","org.gradle.jvmargs=-Xmx2048m -Dfile.encoding=UTF-8\nandroid.useAndroidX=true\n");f.put("app/build.gradle","plugins { id 'com.android.application' }\nandroid { namespace '"+pkg+"'\n compileSdk 35\n defaultConfig { applicationId '"+pkg+"'; minSdk 26; targetSdk 35; versionCode 1; versionName '1.0' }\n compileOptions { sourceCompatibility JavaVersion.VERSION_17; targetCompatibility JavaVersion.VERSION_17 }\n}\n");f.put("app/src/main/AndroidManifest.xml","<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\"><application android:theme=\"@android:style/Theme.Material.Light.NoActionBar\" android:label=\"My App\"><activity android:name=\".MainActivity\" android:exported=\"true\"><intent-filter><action android:name=\"android.intent.action.MAIN\"/><category android:name=\"android.intent.category.LAUNCHER\"/></intent-filter></activity></application></manifest>\n");f.put("app/src/main/java/"+pkg.replace('.','/')+"/MainActivity.java","package "+pkg+";\nimport android.app.Activity; import android.os.Bundle; import android.graphics.Color; import android.view.Gravity; import android.widget.TextView;\npublic class MainActivity extends Activity { public void onCreate(Bundle b) { super.onCreate(b); TextView t=new TextView(this); t.setText(\"Hello from DevStudio!\"); t.setTextSize(24); t.setTextColor(Color.WHITE); t.setGravity(Gravity.CENTER); t.setBackgroundColor(Color.rgb(20,25,34)); setContentView(t); } }\n");f.put("README.md","# Android project\n\nCreated with DevStudio. Commits trigger an APK build.\n");f.put(".github/workflows/build-apk.yml","name: Build Android APK\non:\n  push:\n    branches: [ \"main\" ]\n  workflow_dispatch:\npermissions:\n  contents: read\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: '17'\n      - uses: gradle/actions/setup-gradle@v4\n        with:\n          gradle-version: '8.9'\n      - run: gradle --no-daemon assembleDebug\n      - uses: actions/upload-artifact@v4\n        with:\n          name: Android-debug-APK\n          path: app/build/outputs/apk/debug/app-debug.apk\n          retention-days: 14\n");return f;}
void createDialog(){if(!connected())return;LinearLayout box=col();EditText n=new EditText(this);n.setSingleLine(true);n.setHint("Repository/project name");box.addView(n);EditText p=new EditText(this);p.setSingleLine(true);p.setHint("Package name");p.setText("com.example.app");box.addView(p);new AlertDialog.Builder(this).setTitle("Create Android project").setMessage("Creates a private GitHub repo with Android Gradle files and automatic APK workflow.").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Create",(d,w)->{String name=n.getText().toString().trim().replaceAll("[^A-Za-z0-9_.-]","-"),pkg=p.getText().toString().trim();if(name.isEmpty()||!pkg.matches("[A-Za-z][A-Za-z0-9_]*(\\.[A-Za-z][A-Za-z0-9_]*)+")){toast("Check project and package names");return;}createRemote(name,pkg);}).show();}
void createRemote(String name,String pkg){toast("Creating GitHub repository…");ex.execute(()->{try{String token=sec.getString("github_token","");JSONObject b=new JSONObject();b.put("name",name);b.put("private",true);b.put("description","Android project created with DevStudio");String full=api(token,"POST","/user/repos",b).getString("full_name");LinkedHashMap<String,String> f=starter(pkg);String initial="README.md";JSONObject first=new JSONObject();first.put("message","Initial project from DevStudio");first.put("content",Base64.getEncoder().encodeToString(f.get(initial).getBytes(StandardCharsets.UTF_8)));api(token,"PUT","/repos/"+full+"/contents/"+initial,first);for(Map.Entry<String,String> e:f.entrySet()){if(e.getKey().equals(initial))continue;JSONObject fileBody=new JSONObject();fileBody.put("message","Add "+e.getKey());fileBody.put("content",Base64.getEncoder().encodeToString(e.getValue().getBytes(StandardCharsets.UTF_8)));fileBody.put("branch","main");api(token,"PUT","/repos/"+full+"/contents/"+pathEnc(e.getKey()),fileBody);}runOnUiThread(()->{repo=full;branch="main";files.clear();files.putAll(f);active="app/src/main/java/"+pkg.replace('.','/')+"/MainActivity.java";sec.edit().putString("last_repo",full).apply();editor();toast("Created "+full);});}catch(Exception e){runOnUiThread(()->err("Project creation failed",e.getMessage()+" Make sure your GitHub token has repository Contents: read/write and Administration: read/write permissions."));}});}
void openDialog(){if(!connected())return;EditText e=new EditText(this);e.setSingleLine(true);e.setHint("owner/repository");e.setText(sec.getString("last_repo",""));new AlertDialog.Builder(this).setTitle("Open GitHub project").setMessage("Enter owner/repository. The repo must be accessible to your token.").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Open",(d,w)->{String s=e.getText().toString().trim().replace("https://github.com/","").replaceAll("/$","");if(!s.matches("[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+")){toast("Use owner/repository");return;}loadRemote(s);}).show();}
void loadRemote(String full){toast("Loading project…");ex.execute(()->{try{String token=sec.getString("github_token","");String b=api(token,"GET","/repos/"+full,null).optString("default_branch","main");JSONArray a=api(token,"GET","/repos/"+full+"/git/trees/"+enc(b)+"?recursive=1",null).optJSONArray("tree");if(a==null)throw new Exception("No repository tree");LinkedHashMap<String,String> loaded=new LinkedHashMap<>();for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);String p=x.optString("path","");if(!"blob".equals(x.optString("type"))||p.isEmpty()||p.endsWith(".png")||p.endsWith(".jpg")||p.endsWith(".jar")||p.endsWith(".apk")||x.optLong("size",0)>250000)continue;JSONObject blob=api(token,"GET","/repos/"+full+"/git/blobs/"+x.getString("sha"),null);if("base64".equals(blob.optString("encoding")))loaded.put(p,new String(Base64.getMimeDecoder().decode(blob.getString("content")),StandardCharsets.UTF_8));}if(loaded.isEmpty())throw new Exception("No readable text files found");runOnUiThread(()->{repo=full;branch=b;files.clear();files.putAll(loaded);active=loaded.keySet().iterator().next();sec.edit().putString("last_repo",full).apply();editor();toast("Opened "+full);});}catch(Exception e){runOnUiThread(()->err("Open project failed",e.getMessage()));}});}
String enc(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(Exception e){return s;}}String pathEnc(String s){StringBuilder b=new StringBuilder();for(String p:s.split("/")){if(b.length()>0)b.append('/');b.append(enc(p));}return b.toString();}
JSONObject api(String token,String method,String path,JSONObject body)throws Exception{HttpURLConnection c=null;try{c=(HttpURLConnection)new URL("https://api.github.com"+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("X-GitHub-Api-Version","2022-11-28");c.setRequestProperty("User-Agent","DevStudio-Android");if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();InputStream in=code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null){byte[] z=new byte[8192];int n;while((n=in.read(z))!=-1)out.write(z,0,n);}String s=out.toString("UTF-8");if(code<200||code>=300){String m="GitHub HTTP "+code;try{m=new JSONObject(s).optString("message",m);}catch(Exception ignored){}throw new Exception(m);}return s.isEmpty()?new JSONObject():new JSONObject(s);}finally{if(c!=null)c.disconnect();}}
